<script setup>
import { onMounted, ref } from 'vue';import { useI18n } from 'vue-i18n';import * as api from '../api/notifications';
const { t, locale } = useI18n();const data = ref(null), error = ref(false), busy = ref(false);
async function load(page = 1, legacyPage = 1) { error.value = false; try { data.value = await api.fetchManagement(page, legacyPage); } catch { error.value = true; } }
function savePolicy(row) { return act(() => api.savePolicy({ type: row.type, in_app: row.in_app, email: row.email })); }
function retryLegacy(id) { return act(() => api.retryTransactionalDelivery(id)); }
function retry(id) { return act(() => api.retryDelivery(id)); }
async function act(operation) { if (busy.value) return; busy.value = true; error.value = false; try { await operation(); await load(); } catch { error.value = true; } finally { busy.value = false; } }
onMounted(load);
</script>
<template><section class="mx-auto max-w-5xl space-y-5 p-4" :dir="locale === 'ar' ? 'rtl' : 'ltr'"><h1 class="text-2xl font-black">{{ t('notifications.management') }}</h1><p v-if="error" role="alert" class="text-red-700">{{ t('notifications.error') }}</p><p v-if="!data" role="status">{{ t('notifications.loading') }}</p><template v-else><div class="flex flex-wrap gap-3"><p v-for="(count, status) in data.statistics" :key="status" class="rounded-xl bg-brand-soft p-4">{{ t(`notifications.statuses.${status}`) }}: {{ count }}</p></div><h2 class="text-xl font-bold">{{ t('notifications.failures') }}</h2><article v-for="item in data.failures.data" :key="item.id" class="flex flex-wrap items-center gap-4 rounded-xl border border-slate-200 p-4"><span>{{ item.type }} · {{ item.error_code }} · {{ item.attempts }}</span><button type="button" class="min-h-11 px-3 text-brand" :disabled="busy" @click="retry(item.id)">{{ t('notifications.retry') }}</button></article><div v-if="data.failures.last_page > 1" class="flex justify-between"><button type="button" class="min-h-11 px-3" :disabled="data.failures.current_page <= 1" @click="load(data.failures.current_page - 1)">{{ t('notifications.previous') }}</button><button type="button" class="min-h-11 px-3" :disabled="data.failures.current_page >= data.failures.last_page" @click="load(data.failures.current_page + 1)">{{ t('notifications.next') }}</button></div><h2 class="text-xl font-bold">{{ t('notifications.legacyStatistics') }}</h2><div class="flex flex-wrap gap-3"><p v-for="(count, status) in data.legacy_statistics" :key="status" class="rounded-xl bg-brand-soft p-4">{{ t(`notifications.statuses.${status}`) }}: {{ count }}</p></div><article v-for="item in data.legacy_failures?.data" :key="item.id" class="flex flex-wrap items-center gap-4 rounded-xl border border-slate-200 p-4"><span>{{ item.message_type }} · {{ item.error_code }} · {{ item.attempts }}</span><button v-if="data.can_retry_legacy" type="button" class="min-h-11 px-3 text-brand" :disabled="busy" @click="retryLegacy(item.id)">{{ t('notifications.retry') }}</button></article><div v-if="data.legacy_failures?.last_page > 1" class="flex justify-between"><button type="button" class="min-h-11 px-3" :disabled="data.legacy_failures.current_page <= 1" @click="load(data.failures.current_page, data.legacy_failures.current_page - 1)">{{ t('notifications.previous') }}</button><button type="button" class="min-h-11 px-3" :disabled="data.legacy_failures.current_page >= data.legacy_failures.last_page" @click="load(data.failures.current_page, data.legacy_failures.current_page + 1)">{{ t('notifications.next') }}</button></div><h2 class="text-xl font-bold">{{ t('notifications.policies') }}</h2><form v-for="row in data.catalog" :key="row.type" class="flex flex-wrap items-center gap-4 rounded-xl border border-slate-200 bg-white p-4" @submit.prevent="savePolicy(row)"><span class="min-w-40 flex-1 font-bold">{{ row[locale] }}</span><label><input v-model="row.in_app" type="checkbox" :disabled="row.mandatory"> {{ t('notifications.inApp') }}</label><label><input v-model="row.email" type="checkbox" :disabled="row.mandatory_email"> {{ t('notifications.email') }}</label><button class="min-h-11 px-3 text-brand" :disabled="busy">{{ t('notifications.save') }}</button></form></template></section></template>
